import math

def get_order(base, modulus):
    """Calculates the multiplicative order of base modulo modulus."""
    if math.gcd(base, modulus) != 1:
        return None

    phi = modulus - 1 # Not strictly needed, but useful context

    # Find factors of phi(modulus)
    # For 625 = 5^4, phi(625) = 500.

    def prime_factorization(n):
        factors = {}
        d = 2
        temp = n
        while d * d <= temp:
            while temp % d == 0:
                factors[d] = factors.get(d, 0) + 1
                temp //= d
            d += 1
        if temp > 1:
            factors[temp] = factors.get(temp, 0) + 1
        return factors

    factors = prime_factorization(500) # Factors of 500: {2: 2, 5: 3}

    order = 500

    # Test divisors
    for p in factors:
        for k in range(1, factors[p] + 1):
            test_exponent = order // (p**k)

            # Check if order can be reduced by dividing by p
            # We only need to check for p=2 and p=5

            # Simpler approach: Iterate through prime factors of 500 (2, 5)

            current_order = order
            for p_factor in [2, 5]:
                while current_order % p_factor == 0:
                    test_order = current_order // p_factor
                    if pow(base, test_order, modulus) == 1:
                        current_order = test_order
                    else:
                        break
            return current_order

# Base 3, Modulus 625
L2 = get_order(3, 625)
print(f"L2 (order of 3 mod 625): {L2}")
